int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->dct = get_bits1(gb);

    skip_bits(gb, 3);

    ctx->temporal_reference = get_bits(gb, 10);
    skip_bits(gb, 1);

    int vop_structure = get_bits1(gb);
    int picture_type = get_bits(gb, 2);

    if (picture_type == 0) {
        ctx->reset_predictor = 1;
        ctx->scanning_table = 0;
    } else {
        ctx->reset_predictor = 0;
        ctx->scanning_table = 1;
    }

    ctx->default_matrices = 1;
    ctx->user_data = get_bits1(gb);

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->intra_dct = get_bits1(gb);

    skip_bits(gb, 2); // temporal reference
    skip_bits1(gb);    // VOP structure

    ctx->picture_type = get_bits(gb, 2);

    if (ctx->picture_type == 0) {
        ctx->reset_predictors = 1;
        ctx->scan_table = default_intra_scan;
    } else if (ctx->picture_type == 1) {
        ctx->reset_predictors = 1;
        ctx->scan_table = default_inter_scan;
    } else {
        ctx->reset_predictors = 0;
    }

    load_default_matrices(ctx);

    // Process user data
    while (get_bits1(gb)) {
        skip_bits1(gb);
    }

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->pict_type = get_bits1(gb);
    ctx->f_code = get_bits(gb, 4);
    skip_bits1(gb); /* vop_coding_type */

    ctx->time_increment = get_bits(gb, 10);
    ctx->vop_time_increment = ctx->time_increment;

    if (ctx->pict_type == 0) {
        ctx->pred_x[0] = ctx->pred_y[0] = 0;
        ctx->pred_x[1] = ctx->pred_y[1] = 0;
    }

    int vop_structure = get_bits1(gb);
    int vop_format = get_bits(gb, 2);
    skip_bits(gb, 3); /* vop_quant */

    ctx->interlaced = 0;
    ctx->top_field_first = 0;

    if (vop_structure == 1) {
        ctx->top_field_first = get_bits1(gb);
    }

    ctx->chroma_format = 1;
    ctx->intra_dc_precision = get_bits(gb, 2);

    for (int i = 0; i < 6; i++) {
        ctx->intra_vlc_threshold[i] = 0;
    }

    for (int i = 0; i < 6; i++) {
        ctx->inter_vlc_threshold[i] = 0;
    }

    ctx->load_intra_quantiser_matrix = 0;
    ctx->load_inter_quantiser_matrix = 0;

    for (int i = 0; i < 64; i++) {
        ctx->intra_matrix[i] = 16;
        ctx->inter_matrix[i] = 16;
    }

    return 0;
}

int decode_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->frame_type = get_bits1(gb);
    ctx->dct_type = get_bits1(gb);

    skip_bits(gb, 1); // temporal reference
    skip_bits(gb, 1); // VOP structure

    int picture_type = get_bits(gb, 2);

    if (picture_type == P_TYPE) {
        reset_predictors(ctx);
        configure_scanning_tables(ctx);
    }

    load_default_matrices(ctx);
    process_user_data(ctx, gb);

    return 0;
}

int decode_studio_vop_header(Mpeg4DecContext *ctx, GetBitContext *gb) {
    if (get_bits_left(gb) < 0)
        return 0;

    ctx->current_picture_ptr = NULL;
    ctx->frame_type = 0;
    ctx->inter_dct = 0;

    skip_bits(gb, 1); // skip temporal_reference
    skip_bits(gb, 1); // skip VOP structure info

    int picture_type = get_bits(gb, 2);
    if (picture_type == 0) {
        ctx->predictor_reset();
        ctx->load_default_matrices();
    }

    ctx->process_user_data(gb);

    return 0;
}
